import { useSyncExternalStore } from 'react'

// Native only. Modal overlays render in a portal next to the app, so TalkBack
// and VoiceOver could still move to the screen behind an open dialog, sheet or
// drawer. Every modal surface reports itself here while open (through
// useBackToClose), and UniversalProvider hides the app from screen readers
// while any is open.

let openCount = 0
const listeners = new Set<() => void>()

const subscribe = (listener: () => void) => {
  listeners.add(listener)
  return () => {
    listeners.delete(listener)
  }
}

/** Marks one modal surface as open. Returns the function that marks it closed. */
export function openModalLayer(): () => void {
  openCount += 1
  for (const listener of listeners) listener()
  let closed = false
  return () => {
    if (closed) return
    closed = true
    openCount -= 1
    for (const listener of listeners) listener()
  }
}

/** True while any modal surface is open. */
export function useModalLayerOpen(): boolean {
  return useSyncExternalStore(
    subscribe,
    () => openCount > 0,
    () => false,
  )
}

import { createContext, useContext } from 'react'

export interface AppShellContextValue {
  /** Whether the phone drawer is open. Always false at desktop sizes. */
  sidebarOpen: boolean
  setSidebarOpen: (open: boolean) => void
}

export const AppShellContext = createContext<AppShellContextValue | null>(null)

/**
 * Where a Sidebar is rendered inside an AppShell: the desktop slot or the
 * phone drawer. The slot is the navigation landmark, so a Sidebar inside it
 * drops its own; in the drawer it also fills the drawer, never collapses, and
 * closes the drawer when an item is pressed. It lives with the hooks, not in
 * AppShell.tsx, so a Sidebar copied with the CLI does not bring the shell along.
 */
export const AppShellSlotContext = createContext<'inline' | 'drawer' | null>(null)

/** The AppShell's drawer state, for your own menu buttons. Outside an AppShell it is always closed. */
export function useAppShell(): AppShellContextValue {
  return useContext(AppShellContext) ?? { sidebarOpen: false, setSidebarOpen: () => {} }
}

import { useEffect, useRef } from 'react'
import { BackHandler } from 'react-native'
import { openModalLayer } from './modalLayer'
import type { BackToCloseOptions } from './useBackToClose'

/**
 * Android: while `open`, the hardware back button (or back gesture) calls
 * `close` instead of going back in the app's navigation. Listeners run newest
 * first, so an open overlay handles the press before the router, and a nested
 * overlay before its parent. iOS has no back button, so there it never fires;
 * web uses useBackToClose.ts, which does nothing.
 *
 * Tamagui's Dialog, Sheet and Popover render in portals with no back handling
 * of their own, so every modal surface calls this from its root. While open it
 * also counts as a modal layer, so UniversalProvider hides the screen behind it
 * from TalkBack and VoiceOver (iOS and Android). A panel that opens in place,
 * inside the screen, passes `{ modal: false }`.
 */
export function useBackToClose(
  open: boolean,
  close: () => void,
  { modal = true }: BackToCloseOptions = {},
) {
  // Latest `close` without re-subscribing, which would reorder the listeners.
  const closeRef = useRef(close)
  useEffect(() => {
    closeRef.current = close
  })

  useEffect(() => {
    if (!open) return
    const subscription = BackHandler.addEventListener('hardwareBackPress', () => {
      closeRef.current()
      return true
    })
    const closeLayer = modal ? openModalLayer() : null
    return () => {
      subscription.remove()
      closeLayer?.()
    }
  }, [open, modal])
}

/**
 * Android: while `open`, the hardware back button (or back gesture) calls
 * `close` instead of going back in the app's navigation. See
 * useBackToClose.native.ts. Browsers have no back button to intercept here
 * (react-native-web's BackHandler only warns), so on web it does nothing.
 */
export function useBackToClose(_open: boolean, _close: () => void, _options?: BackToCloseOptions) {}

export interface BackToCloseOptions {
  /**
   * Native: hide the screen behind from screen readers while open. On by
   * default, for overlays in a portal; off for a panel that opens in place.
   */
  modal?: boolean
}

import { getConfig, useDidFinishSSR, useMedia } from 'tamagui/unstyled'
import {
  type Breakpoint,
  type Responsive,
  breakpointKeys,
  resolveResponsive,
} from '../utils/responsive'

/**
 * The largest min-width breakpoint the window matches, or `'base'` below `xs`.
 * It re-renders when that changes.
 *
 * The server can't know the width, so it renders for a phone (the config's
 * `mediaQueryDefaultActive`, `xs` here). Until hydration finishes the client
 * returns the same, so the markup matches and React logs no hydration error,
 * then it re-renders with the real breakpoint. Lay pages out with Show / Hide
 * or responsive props, which are CSS on web, and keep this for behavior.
 */
export function useBreakpoint(): 'base' | Breakpoint {
  const media = useMedia()
  const hydrated = useDidFinishSSR()
  const active: Record<string, boolean | undefined> = hydrated
    ? media
    : (getConfig().settings.mediaQueryDefaultActive ?? {})
  let current: 'base' | Breakpoint = 'base'
  for (const key of breakpointKeys) if (active[key]) current = key
  return current
}

/**
 * The value of a responsive prop at the current breakpoint, with the same
 * mobile-first cascade as the layout props: `{ base: 1, md: 3 }` is 1 below md
 * and 3 from md. `undefined` below the first breakpoint of a map without `base`.
 */
export function useBreakpointValue<T>(value: Responsive<T>): T | undefined {
  return resolveResponsive(value, useBreakpoint())
}

import { useCallback, useState } from 'react'

/**
 * State that can be either controlled (`value` + `onChange`) or uncontrolled
 * (`defaultValue`). Every stateful component uses this so both styles work.
 */
export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
}: {
  value?: T
  defaultValue: T
  onChange?: (next: T) => void
}): [T, (next: T | ((prev: T) => T)) => void] {
  const [internal, setInternal] = useState(defaultValue)
  const isControlled = value !== undefined
  const current = isControlled ? value : internal

  const setValue = useCallback(
    (next: T | ((prev: T) => T)) => {
      const resolved = typeof next === 'function' ? (next as (prev: T) => T)(current) : next
      if (Object.is(resolved, current)) return
      if (!isControlled) setInternal(resolved)
      onChange?.(resolved)
    },
    [current, isControlled, onChange],
  )

  return [current, setValue]
}

import { StyleSheet, View } from 'react-native'
import { getTokenValue, useTheme } from 'tamagui/unstyled'
import type { DashedBorder } from './useDashedBorder'

const none: DashedBorder = { frame: undefined, overlay: null }

/**
 * Android dashes a rounded border only when it has `borderWidth` and
 * `borderColor` for all sides. Tamagui splits both into per-side props on
 * native, its `style` prop included since Tamagui 3, and Android draws those
 * solid. So the frame's own border turns transparent (it keeps its width, and
 * the layout) and a plain React Native view on top draws the dashes, in
 * `color` from the theme with the frame's `radius`. `null` draws none.
 */
export function useDashedBorder(color: string | null, radius: string): DashedBorder {
  const theme = useTheme()
  if (color === null) return none
  const name = color.startsWith('$') ? color.slice(1) : color
  const variable = theme[name as keyof typeof theme] as { val: string } | undefined
  const borderRadius = getTokenValue(radius as never, 'radius') as number | undefined
  return {
    frame: { borderColor: 'transparent' },
    overlay: (
      <View
        pointerEvents="none"
        // Over the frame's 1px border, which the absolute fill sits inside.
        style={[
          StyleSheet.absoluteFill,
          {
            top: -1,
            right: -1,
            bottom: -1,
            left: -1,
            borderWidth: 1,
            borderStyle: 'dashed',
            borderColor: variable?.val,
            borderRadius,
          },
        ]}
      />
    ),
  }
}

import type { ReactNode } from 'react'

/** A frame style, and an element drawn over the frame, that keep its dashed border dashed. */
export interface DashedBorder {
  frame: { borderColor: 'transparent' } | undefined
  overlay: ReactNode
}

/**
 * What keeps a rounded dashed border dashed on native (see
 * `useDashedBorder.native.tsx`). Web needs none: its border is already dashed.
 */
export function useDashedBorder(_color: string | null, _radius: string): DashedBorder {
  return { frame: undefined, overlay: null }
}

import { createContext, useContext } from 'react'
import { isWeb } from 'tamagui/unstyled'
import { useLabelFor } from './useLabelFor'
import { FormContext } from './useParentForm'

/** What a Field tells the control inside it. */
export interface FieldState {
  /** The control's id; the field's label targets it. */
  id: string
  /** The label's id, for controls a `<label for>` cannot name, such as a radio group. */
  labelId?: string
  /** The label's text, with "required" or "(optional)": the control's name on native. */
  label?: string
  /** Ids of the error and help text (web). */
  describedBy?: string
  /** The text of the error and help text: the control's hint on native. */
  hint?: string
  invalid: boolean
  required: boolean
  disabled: boolean
}

/** Set by Field. A control that renders other controls inside resets it to null for them. */
export const FieldContext = createContext<FieldState | null>(null)

/**
 * Tamagui 3 types every variant prop as a flat value too (`'a hover:b'`). A
 * control's `disabled` and `invalid` are plain booleans: omit the frame's
 * and take these.
 */
export interface ControlStateProps {
  disabled?: boolean
  invalid?: boolean
}

/** The props a Field sets on its control. The core form controls all accept them. */
export interface FieldControlProps {
  id?: string
  invalid?: boolean
  disabled?: boolean
  'aria-describedby'?: string
  'aria-required'?: boolean | 'true' | 'false'
  'aria-label'?: string
  accessibilityHint?: string
}

const joinIds = (...lists: Array<string | undefined>) =>
  [...new Set(lists.join(' ').split(' ').filter(Boolean))].join(' ')

/**
 * Fills in what the surrounding Field decides: the id its label targets,
 * `invalid`, `disabled`, `aria-required`, and the links to its help and error
 * text. The control's own props win, `invalid` and `disabled` add up, and
 * outside a Field the props come back unchanged, except that a disabled Form
 * disables the control with or without a Field, and that on native a `<Label
 * htmlFor>` names the control with its id. Call it in your own controls so a
 * Field, a Form and a Label wire them like the core ones.
 */
export function useFieldControl<P extends object>(controlProps: P): P {
  // Tamagui 3 widens variant props (`invalid`, `disabled`) to flat values in
  // GetProps types; controls pass plain values, which is what this reads.
  const props = controlProps as P & FieldControlProps
  const field = useContext(FieldContext)
  const form = useContext(FormContext)
  // Native: a Label's htmlFor only moves focus, so its text names the control.
  const unnamed = !isWeb && props['aria-label'] === undefined && field?.label === undefined
  const labelText = useLabelFor(unnamed ? (props.id ?? field?.id) : undefined)
  if (!field) {
    const named = labelText === undefined ? props : { ...props, 'aria-label': labelText }
    return form.disabled && !props.disabled ? { ...named, disabled: true } : named
  }
  // Joined without repeats, so a control that passes the result on to an inner
  // control (Password Input to Input) gets the same props a second time.
  const describedBy = joinIds(props['aria-describedby'], field.describedBy)
  return {
    ...props,
    id: props.id ?? field.id,
    ...((field.invalid || props.invalid) && { invalid: true }),
    ...((field.disabled || props.disabled) && { disabled: true }),
    ...(field.required && props['aria-required'] === undefined && { 'aria-required': true }),
    ...(isWeb
      ? describedBy && { 'aria-describedby': describedBy }
      : {
          // A Label's htmlFor only moves focus on native, so the field names the
          // control. Native has no aria-describedby: the texts are the hint.
          ...(props['aria-label'] === undefined &&
            (field.label ?? labelText) !== undefined && {
              'aria-label': field.label ?? labelText,
            }),
          ...(props.accessibilityHint === undefined &&
            field.hint !== undefined && { accessibilityHint: field.hint }),
        }),
  }
}

import { useEffect, useSyncExternalStore } from 'react'

// Native only. A Label's `htmlFor` only moves focus on iOS and Android, so the
// Label publishes its text for the id it targets, and the control with that id
// takes it as its name (through useFieldControl), as a Field's label does.
// While a control uses the text, the Label is hidden from screen readers so the
// name is not read twice. Labels and controls are often siblings, so they meet
// here by id rather than through context.

interface Entry {
  text?: string
  owner?: object
  users: number
}

const entries = new Map<string, Entry>()
const listeners = new Set<() => void>()

const emit = () => {
  for (const listener of listeners) listener()
}

const subscribe = (listener: () => void) => {
  listeners.add(listener)
  return () => {
    listeners.delete(listener)
  }
}

const entryFor = (id: string) => {
  let entry = entries.get(id)
  if (!entry) {
    entry = { users: 0 }
    entries.set(id, entry)
  }
  return entry
}

const release = (id: string, entry: Entry) => {
  if (entry.text === undefined && entry.users === 0) entries.delete(id)
  emit()
}

/**
 * Label side: offers `text` as the name of the control whose id is `htmlFor`.
 * Returns true while a control uses it. Pass `undefined` on web.
 */
export function usePublishLabel(htmlFor: string | undefined, text: string | undefined): boolean {
  useEffect(() => {
    if (!htmlFor || !text) return
    const owner = {}
    const entry = entryFor(htmlFor)
    entry.text = text
    entry.owner = owner
    emit()
    return () => {
      // Another Label may have taken the id since.
      if (entry.owner !== owner) return
      entry.text = undefined
      entry.owner = undefined
      release(htmlFor, entry)
    }
  }, [htmlFor, text])
  const used = () => Boolean(htmlFor && text && (entries.get(htmlFor)?.users ?? 0) > 0)
  return useSyncExternalStore(subscribe, used, () => false)
}

// The ids in an id list (`aria-labelledby`), or none.
const idList = (ids: string | undefined) => (ids ? ids.split(/\s+/).filter(Boolean) : [])

/**
 * Control side: the text of a Label that targets `id`, for a control without a
 * name of its own. Pass `undefined` on web or when the control is named. A
 * Label also publishes under its own id, so a control can pass its
 * `aria-labelledby` instead: a list of ids gives their texts joined, as a
 * browser names it (ids hold no spaces, so a single id is a list of one).
 */
export function useLabelFor(id: string | undefined): string | undefined {
  useEffect(() => {
    const ids = idList(id)
    const used = ids.map((each) => [each, entryFor(each)] as const)
    if (!used.length) return
    for (const [, entry] of used) entry.users += 1
    emit()
    return () => {
      for (const [each, entry] of used) {
        entry.users -= 1
        release(each, entry)
      }
    }
  }, [id])
  const text = () => {
    const texts = idList(id).flatMap((each) => entries.get(each)?.text ?? [])
    return texts.length ? texts.join(' ') : undefined
  }
  return useSyncExternalStore(subscribe, text, () => undefined)
}

import { type ReactNode, createContext, useContext } from 'react'

export interface FormContextValue {
  /** The form does not accept input. Form controls and Form.Submit follow it. */
  disabled: boolean
  /** The app is submitting the form. The app owns this state; the form only shows it. */
  loading: boolean
  /** What the form says while loading, e.g. "Saving…". */
  loadingText?: ReactNode
  /** Calls the form's `onSubmit`, unless it is disabled or loading. Does nothing outside a Form. */
  submit: () => void
}

const outsideForm: FormContextValue = { disabled: false, loading: false, submit: () => {} }

/** Set by Form; read by the controls inside it. */
export const FormContext = createContext<FormContextValue>(outsideForm)

/**
 * The surrounding Form, for your own fields and actions: a custom submit
 * button calls `submit`, a custom control follows `disabled`. Not named
 * `useFormStatus`, so it is not mistaken for React DOM's hook of that name.
 */
export function useParentForm(): FormContextValue {
  return useContext(FormContext)
}

/** @deprecated Renamed to `useParentForm`. This alias will be removed in a future release. */
export const useFormStatus = useParentForm
/** @deprecated Renamed to `FormContextValue`. */
export type FormStatus = FormContextValue

import { useEffect, useState } from 'react'
import { AccessibilityInfo } from 'react-native'

/** `true` when "Reduce Motion" (iOS) / "Remove animations" (Android) is enabled. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false)

  useEffect(() => {
    let mounted = true
    AccessibilityInfo.isReduceMotionEnabled().then((value) => {
      if (mounted) setReduced(value)
    })
    const subscription = AccessibilityInfo.addEventListener('reduceMotionChanged', setReduced)
    return () => {
      mounted = false
      subscription.remove()
    }
  }, [])

  return reduced
}

import { useEffect, useState } from 'react'

const QUERY = '(prefers-reduced-motion: reduce)'

/** `true` when the user asked the OS/browser to minimise motion. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false)

  useEffect(() => {
    if (typeof window === 'undefined' || !window.matchMedia) return
    const query = window.matchMedia(QUERY)
    const update = () => setReduced(query.matches)
    update()
    query.addEventListener('change', update)
    return () => query.removeEventListener('change', update)
  }, [])

  return reduced
}

import { getUniversalSettings } from '@advui/theme'
import { type ComponentRef, forwardRef, useMemo, useRef } from 'react'
import { Platform, StyleSheet, View, codegenNativeCommands, processColor } from 'react-native'
import { type ColorTokens, getConfig, useTheme } from 'tamagui/unstyled'
import type { Ripple, RippleOptions } from './useRipple'

type Host = ComponentRef<typeof View>

interface ViewCommands {
  hotspotUpdate: (view: Host, x: number, y: number) => void
  setPressed: (view: Host, pressed: boolean) => void
}

// The view commands Pressable sends for `android_ripple`, created on first use.
let commands: ViewCommands | undefined
const viewCommands = () =>
  (commands ??= codegenNativeCommands<ViewCommands>({
    supportedCommands: ['hotspotUpdate', 'setPressed'],
  }))

// Material's pressed state layer is 10%. Android paints ripples below their
// color's alpha, so Material Components and Compose pass double that; so do
// we, to match native Material apps.
const RIPPLE_ALPHA = 0.2

type TouchEvent = {
  nativeEvent?: { pageX?: number; pageY?: number; locationX?: number; locationY?: number }
}

// Where the ripple starts. `locationX/Y` are relative to the touched child
// (such as the label), so measure from the ripple view when the host can.
function hotspot(view: Host, event: unknown) {
  const touch = (event as TouchEvent | undefined)?.nativeEvent
  if (!touch) return null
  const rect = (view as { getBoundingClientRect?: () => DOMRect }).getBoundingClientRect?.()
  if (rect && touch.pageX !== undefined && touch.pageY !== undefined) {
    return { x: touch.pageX - rect.left, y: touch.pageY - rect.top }
  }
  return { x: touch.locationX ?? 0, y: touch.locationY ?? 0 }
}

const RippleHost = forwardRef<Host, { color: ColorTokens }>(function RippleHost({ color }, ref) {
  const theme = useTheme()
  const name = color.startsWith('$') ? color.slice(1) : color
  const value = (theme[name as keyof typeof theme] as { val: string } | undefined)?.val
  const background = useMemo(
    () => ({
      type: 'RippleAndroid',
      color: processColor(value),
      borderless: false,
      // No rippleRadius key: Android reads it as a number when present.
      alpha: RIPPLE_ALPHA,
    }),
    [value],
  )
  return (
    <View
      ref={ref}
      pointerEvents="none"
      importantForAccessibility="no-hide-descendants"
      collapsable={false}
      style={StyleSheet.absoluteFill}
      // Not in View's public types: it is the prop Pressable's `android_ripple` sets.
      {...{ nativeBackgroundAndroid: background }}
    />
  )
})

export function useRipple({ color, disabled, onPressIn, onPressOut }: RippleOptions): Ripple {
  // Read from the config rather than React context: sheets and toasts render
  // through native portals that do not carry context.
  const enabled =
    Platform.OS === 'android' && !disabled && getUniversalSettings(getConfig()).androidRipple
  const host = useRef<Host>(null)

  if (!enabled) {
    return {
      active: false,
      props: { ...(onPressIn && { onPressIn }), ...(onPressOut && { onPressOut }) },
      element: null,
    }
  }

  return {
    active: true,
    props: {
      // Clips the ripple to the element's rounded corners. Android clips
      // inside the border, so a transparent border leaves an unrippled ring.
      overflow: 'hidden',
      onPressIn: (event) => {
        onPressIn?.(event)
        const view = host.current
        if (!view) return
        const point = hotspot(view, event)
        if (point) viewCommands().hotspotUpdate(view, point.x, point.y)
        viewCommands().setPressed(view, true)
      },
      onPressOut: (event) => {
        onPressOut?.(event)
        if (host.current) viewCommands().setPressed(host.current, false)
      },
    },
    element: <RippleHost ref={host} color={color} />,
  }
}

import type { ReactNode } from 'react'
import type { ColorTokens, GetProps, View } from 'tamagui/unstyled'

type PressHandler = GetProps<typeof View>['onPressIn']

export interface RippleOptions {
  /** Color of the content on the surface, e.g. `primaryForeground`. */
  color: ColorTokens
  /** No ripple, e.g. while disabled or when the element is not pressable. */
  disabled?: boolean
  /** Your own handlers. They still run. */
  onPressIn?: PressHandler
  onPressOut?: PressHandler
}

export interface Ripple {
  /**
   * The ripple replaces the pressed style, so drop your `press:`
   * background while this is true. It is clipped inside the border, so drop
   * a transparent border too.
   */
  active: boolean
  /** Spread on the pressable element, after its other props. */
  props: { overflow?: 'hidden'; onPressIn?: PressHandler; onPressOut?: PressHandler }
  /** Render as the first child of the pressable element. */
  element: ReactNode
}

/**
 * The Android press ripple for your own pressables, drawn when the config has
 * `androidRipple` (as `material()` does). On web and iOS it does nothing.
 *
 * @example
 * const ripple = useRipple({ color: 'foreground', onPressIn, onPressOut })
 * <View onPress={open} {...ripple.props}>
 *   {ripple.element}
 *   <Text>Inbox</Text>
 * </View>
 */
export function useRipple({ onPressIn, onPressOut }: RippleOptions): Ripple {
  return {
    active: false,
    props: { ...(onPressIn && { onPressIn }), ...(onPressOut && { onPressOut }) },
    element: null,
  }
}

import { Dimensions } from 'react-native'
import { getTokenValue, useConfiguration, useWindowDimensions } from 'tamagui/unstyled'

/**
 * The tallest a bottom sheet's frame may be. Tamagui grows a `fit` sheet to
 * its content, up to the whole screen, so a long menu or list (or a short one
 * on a phone in landscape) slid under the status bar. Capped at the screen less
 * the top inset (from UniversalProvider) and room for the handle, the sheet's
 * ScrollView scrolls instead. Call it in the component that renders the Sheet:
 * the frame itself renders in a portal, which drops context.
 */
export function useSheetMaxHeight(): number | undefined {
  // Re-renders when the phone turns. The sheet covers the screen, while the
  // window can leave out the system bars, so the screen is what it is measured
  // against (as Tamagui does).
  useWindowDimensions()
  const top = useConfiguration().insets?.top ?? 0
  return Dimensions.get('screen').height - top - (getTokenValue('8', 'space') as number)
}

/**
 * Web: no cap. A bottom sheet there (Select on touch devices) has no status bar
 * to keep clear. The native file caps sheets below the status bar.
 */
export function useSheetMaxHeight(): number | undefined {
  return undefined
}
